-- Fun pack: coin ledger, achievements, daily guess game, predictions, crates, quotes, bounties, birthdays, Steam sales, weekly recap.
-- Run in the D1 console before pushing.
CREATE TABLE IF NOT EXISTS coin_awards ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, source TEXT NOT NULL, ref TEXT NOT NULL, coins INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE (source, ref, user_id) );
ALTER TABLE users ADD COLUMN birthday TEXT;
CREATE TABLE IF NOT EXISTS achievements ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, key TEXT NOT NULL, unlocked_at INTEGER NOT NULL, PRIMARY KEY (user_id, key) );
CREATE TABLE IF NOT EXISTS guess_plays ( day TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, guesses TEXT NOT NULL DEFAULT '[]', solved INTEGER NOT NULL DEFAULT 0, done INTEGER NOT NULL DEFAULT 0, coins INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, user_id) );
CREATE TABLE IF NOT EXISTS markets ( id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, ref TEXT, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', closes_at INTEGER, winner_option INTEGER, created_by INTEGER, created_at INTEGER NOT NULL, UNIQUE (kind, ref) );
CREATE TABLE IF NOT EXISTS market_options ( id INTEGER PRIMARY KEY AUTOINCREMENT, market_id INTEGER NOT NULL REFERENCES markets(id) ON DELETE CASCADE, label TEXT NOT NULL, ref TEXT );
CREATE TABLE IF NOT EXISTS market_bets ( market_id INTEGER NOT NULL REFERENCES markets(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, option_id INTEGER NOT NULL, coins INTEGER NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (market_id, user_id) );
CREATE TABLE IF NOT EXISTS crate_opens ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id TEXT NOT NULL, rarity TEXT NOT NULL, price INTEGER NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS quotes ( id INTEGER PRIMARY KEY AUTOINCREMENT, message_id INTEGER UNIQUE, body TEXT NOT NULL, author_id INTEGER REFERENCES users(id) ON DELETE SET NULL, saved_by INTEGER REFERENCES users(id) ON DELETE SET NULL, said_at INTEGER NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS quote_votes ( quote_id INTEGER NOT NULL REFERENCES quotes(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY (quote_id, user_id) );
CREATE TABLE IF NOT EXISTS bounties ( id INTEGER PRIMARY KEY AUTOINCREMENT, target_uuid TEXT NOT NULL, target_name TEXT NOT NULL, poster_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, coins INTEGER NOT NULL, blood_moon_only INTEGER NOT NULL DEFAULT 0, note TEXT, status TEXT NOT NULL DEFAULT 'open', claimed_by_name TEXT, claimed_by_user INTEGER, claimed_at INTEGER, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS week_baseline ( week_start INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, play_minutes INTEGER NOT NULL, PRIMARY KEY (week_start, user_id) );
CREATE TABLE IF NOT EXISTS steam_prices ( appid INTEGER PRIMARY KEY, discount INTEGER NOT NULL DEFAULT 0, final_price TEXT, initial_price TEXT, checked_at INTEGER NOT NULL DEFAULT 0, notified_discount INTEGER NOT NULL DEFAULT 0 );
